function finishEnding(type){ui.dialogue.classList.add('hidden');closePanel();flags.ending=type;world.ending=type;let title,sub,text;if(type==='best'){title='THE NAMES REMAIN';sub='A TESTAMENT, NOT A CONFESSION';text='The ledger, the fiber, and Mara’s account hold up under scrutiny. Jonah is taken in alive. His confession names the people who financed the congregation, and the dead are finally entered into the county record. Before dawn, the radio speaks your badge number once. Only once.'}else if(type==='good'){title='THE LAST LANTERN';sub='CASE CLOSED · QUESTIONS REMAIN';text='Jonah is arrested beneath the chapel, but the old ledger is incomplete. He gives the county a confession and keeps the names of those who helped him. By morning, the rain has stopped. No one in Gloamwood remembers hearing a bell.'}else{title='THE TOWN CLOSES RANKS';sub='CASE DISMISSED';text='The accusation outruns the evidence. Jonah vanishes into the storm, and the county calls it a misunderstanding. The dispatch channel goes quiet. Somewhere below Old Mercy, a bell rings twice.'}$('endingTitle').textContent=title;$('endingSub').textContent=sub;$('endingText').textContent=text;ui.ending.classList.remove('hidden');save(0,true)}
function findWalkable(x,y){for(let r=1;r<5;r++)for(let dy=-r;dy<=r;dy++)for(let dx=-r;dx<=r;dx++){let xx=x+dx*.5,yy=y+dy*.5;if(!collides(xx,yy))return{x:xx,y:yy}}return{x:player.x,y:player.y}}
function travel(id){const loc=locations.find(l=>l.id===id);if(!loc)return;const pos=findWalkable(loc.x,loc.y);player.x=pos.x;player.y=pos.y;player.angle=-Math.PI/2;player.visited=[...new Set([...player.visited,id])];player.habits[loc.id==='chapel'?'chapel':'public']++;advance(Math.max(8,Math.round(distance(player,loc)*4)),true);closePanel();say(`ARRIVED · ${loc.name}`);save(0,true)}
function closeAll(){if(!ui.dialogue.classList.contains('hidden'))ui.dialogue.classList.add('hidden');if(!ui.panel.classList.contains('hidden'))closePanel();$('helpScreen').classList.add('hidden');document.exitPointerLock?.()}
function handlePanelClick(e){const btn=e.target.closest('button');if(!btn)return;if(btn.dataset.caseTab){openCase(btn.dataset.caseTab);return}if(btn.dataset.travel){travel(btn.dataset.travel);return}if(btn.dataset.do==='save'){save();return}if(btn.dataset.do==='analyze'){flags.analyzed=true;player.habits.forensics++;player.stress=Math.max(0,player.stress-6);evidence.find(x=>x.id==='fiber').analyzed=true;evidence.find(x=>x.id==='fiber').analysis='Consistent with the dark ivory wool coat issued to Nightjar Diner staff. The fiber alone does not establish who wore it or when.';flags.trustMara++;world.events.push('Fiber is consistent with Nightjar staff coat.');advance(45,true);say('LAB RESULT RECEIVED · COMPARISON IS CONSISTENT');save(0,true);openLab();objective()}}
function tick(now){let dt=Math.min(.05,(now-last)/1000);last=now;if(ui.start.classList.contains('hidden')&&ui.ending.classList.contains('hidden')&&ui.dialogue.classList.contains('hidden')&&ui.panel.classList.contains('hidden')){let forward=(keys.KeyW||keys.ArrowUp?1:0)-(keys.KeyS||keys.ArrowDown?1:0),side=(keys.KeyD?1:0)-(keys.KeyA?1:0);if(keys.ArrowLeft)player.angle-=dt*1.9;if(keys.ArrowRight)player.angle+=dt*1.9;if(mouseLook){player.angle+=mouseLook;mouseLook=0}if(forward||side){let speed=(keys.ShiftLeft||keys.ShiftRight?3.5:2.35)*dt,dx=(Math.cos(player.angle)*forward-Math.sin(player.angle)*side)*speed,dy=(Math.sin(player.angle)*forward+Math.cos(player.angle)*side)*speed;if(!collides(player.x+dx,player.y))player.x+=dx;if(!collides(player.x,player.y+dy))player.y+=dy;player.steps+=Math.abs(forward)+Math.abs(side);player.stamina=Math.max(20,player.stamina-(keys.ShiftLeft||keys.ShiftRight?dt*9:-dt*4));if(player.steps>25){player.steps=0;advance(1,true)}}else player.stamina=Math.min(100,player.stamina+dt*6)}draw();updatePrompt();requestAnimationFrame(tick)}
function bind(){document.querySelectorAll('.nav-button').forEach(b=>b.addEventListener('click',()=>{if(b.dataset.panel==='case')openCase('evidence');if(b.dataset.panel==='map')openMap();if(b.dataset.panel==='notes')openNotes()}));$('closePanel').addEventListener('click',closePanel);ui.panelContent.addEventListener('click',handlePanelClick);$('closeDialogue').addEventListener('click',()=>ui.dialogue.classList.add('hidden'));$('dialogueOptions').addEventListener('click',e=>{const b=e.target.closest('[data-choice]');if(b)chooseDialogue(b.dataset.choice)});$('beginBtn').addEventListener('click',()=>{ui.start.classList.add('hidden');advance(0);say('CASE 07-14 · FIELD NOTES OPEN');save(0,true)});$('saveBtn').addEventListener('click',()=>save());$('helpBtn').addEventListener('click',()=>$('helpScreen').classList.remove('hidden'));document.querySelectorAll('.modal-close,.modal-ok').forEach(b=>b.addEventListener('click',()=>$('helpScreen').classList.add('hidden')));$('restartBtn').addEventListener('click',()=>{localStorage.removeItem(SAVE+'0');location.reload()});canvas.addEventListener('click',()=>{if(document.pointerLockElement!==canvas&&ui.start.classList.contains('hidden'))canvas.requestPointerLock?.()});document.addEventListener('pointerlockchange',()=>{});document.addEventListener('mousemove',e=>{if(document.pointerLockElement===canvas&&ui.dialogue.classList.contains('hidden')&&ui.panel.classList.contains('hidden'))player.angle+=e.movementX*.0022});document.addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();keys[e.code]=true;if(e.repeat)return;if(e.code==='KeyE'&&!ui.start.classList.contains('hidden')===false&&ui.ending.classList.contains('hidden'))interact();if(e.code==='KeyF')player.flashlight=!player.flashlight;if(e.code==='Escape'){if(!$('helpScreen').classList.contains('hidden'))$('helpScreen').classList.add('hidden');else closeAll()}if(e.code==='Digit1')openCase('evidence');if(e.code==='Digit2')openMap();if(e.code==='Digit3')openNotes()});document.addEventListener('keyup',e=>keys[e.code]=false);document.addEventListener('visibilitychange',()=>{if(document.hidden)save(0,true)});}
if(!load(Number(localStorage.getItem(SAVE+'active')||0))){objective()}else{ui.start.querySelector('p').innerHTML='A rain-darkened town. A congregation with a secret.<br>Someone is listening.<br><span class="muted">A field notebook from this case was recovered.</span>';objective();say('FIELD NOTES RECOVERED')}
ui.clock.textContent=timeString();ui.weather.textContent=world.weather;bind();requestAnimationFrame(tick);
})();

