.interaction-prompt.visible{opacity:1}
@media (pointer:coarse){
  #view{touch-action:none}
  .mobile-controls{display:flex;position:absolute;z-index:5;inset:auto 0 84px;align-items:flex-end;justify-content:space-between;padding:0 22px;pointer-events:none;touch-action:none}
  .move-pad{width:126px;height:126px;border-radius:50%;display:grid;place-items:center;pointer-events:auto;touch-action:none;background:radial-gradient(circle,rgba(197,169,106,.07),rgba(8,12,11,.36));border:1px solid rgba(229,219,190,.28);box-shadow:inset 0 0 26px #0005,0 8px 26px #0004}
  .move-pad-ring{width:86px;height:86px;border:1px solid rgba(229,219,190,.2);border-radius:50%;display:grid;place-items:center}
  .move-pad-ring i{display:block;width:40px;height:40px;border-radius:50%;background:linear-gradient(145deg,rgba(214,196,151,.72),rgba(107,99,77,.82));border:1px solid rgba(255,244,208,.42);box-shadow:0 3px 12px #0008;transform:translate(0,0)}
  .mobile-actions{display:flex;align-items:flex-end;gap:10px;pointer-events:auto}
  .touch-action{min-width:52px;height:52px;padding:0 10px;border:1px solid rgba(229,219,190,.32);border-radius:50%;background:rgba(12,17,15,.72);box-shadow:0 5px 18px #0007;color:#e4d8b8;font:9px 'DM Mono',monospace;letter-spacing:.6px;touch-action:none;user-select:none;-webkit-user-select:none}
  .touch-action.pressed,.touch-action:active{background:rgba(190,157,92,.42);border-color:var(--gold)}
  .touch-interact{min-width:74px;width:74px;height:74px;border-radius:50%;font-size:8px;color:#f0dfb6;border-color:rgba(213,183,117,.55)}
}

content.text:
*{box-sizing:border-box}
 :root{--ink:#e7e5d9;--muted:#a9aaa0;--faint:#777d76;--gold:#c7a96a;--red:#c76a5b;--panel:rgba(15,20,19,.94);--line:rgba(227,224,205,.14)}
html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#101513;color:var(--ink);font-family:'DM Sans',sans-serif}
button{font:inherit;color:inherit}
#game{position:relative;width:100vw;height:100dvh;min-height:500px;overflow:hidden;background:#111917}
#view{position:absolute;inset:0;width:100%;height:100%;display:block}
.vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,rgba(5,9,9,.7),transparent 18%,transparent 62%,rgba(5,9,9,.78)),radial-gradient(ellipse at center,transparent 30%,rgba(3,7,7,.55) 100%);z-index:1}
.grain{position:absolute;inset:-50%;z-index:2;pointer-events:none;opacity:.075;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.82' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.5'/%3E%3C/svg%3E");animation:grain .3s steps(2) infinite}
@keyframes grain{0%{transform:translate(0,0)}
50%{transform:translate(2%,-1%)}
100%{transform:translate(-1%,2%)}
}
.topbar{position:absolute;z-index:4;left:0;right:0;top:0;height:74px;padding:0 36px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(255,255,255,.09);background:linear-gradient(180deg,rgba(7,11,11,.62),transparent)}
.brand{display:flex;align-items:center;gap:12px}
.brand-mark{font-size:28px;color:var(--gold);line-height:1}
.brand-name{font-size:12px;letter-spacing:2.6px;font-weight:700}
.brand-name span{color:#a7a69d;font-weight:400}
.brand-sub,.case-label{font:10px 'DM Mono',monospace;letter-spacing:1.55px;color:#aca99c}
.brand-sub{font-size:9px;margin-top:4px}
.top-center{display:flex;align-items:center;gap:14px;color:#cac9be;font:10px 'DM Mono',monospace;letter-spacing:1.3px}
.top-center i{height:13px;width:1px;background:rgba(255,255,255,.26)}
.live-dot{height:6px;width:6px;border-radius:50%;background:#c97060;box-shadow:0 0 9px #bd584c}
.top-actions{display:flex;gap:10px}
.icon-btn{height:34px;min-width:36px;border:1px solid rgba(255,255,255,.18);background:rgba(10,14,13,.4);cursor:pointer;color:#d4d1c5}
.icon-btn span{font:9px 'DM Mono',monospace;margin-left:6px}
.icon-btn:hover,.nav-button:hover{border-color:var(--gold);color:var(--gold)}
.hud-left{position:absolute;z-index:3;top:24%;left:5.1%;width:310px;pointer-events:none}
.hud-left h1{font:500 36px/1.12 'Playfair Display',serif;letter-spacing:.1px;margin:12px 0 13px;text-shadow:0 2px 20px #000}
.hud-left p{font-size:13px;line-height:1.6;color:#c5c6bc;max-width:278px;margin:0 0 20px}
.objective-progress{display:flex;align-items:center;gap:12px;font:10px 'DM Mono',monospace;color:#d4c398;letter-spacing:1px;width:235px}
.progress-track{height:2px;background:rgba(255,255,255,.23);flex:1}
.progress-track i{display:block;width:0;height:2px;background:var(--gold);transition:width .5s}
.location-line{font:9px 'DM Mono',monospace;color:#bab9ab;letter-spacing:1.2px;margin-top:26px;display:flex;gap:8px;align-items:center}
.pin{font-size:17px;color:var(--gold)}
.hud-right{position:absolute;z-index:3;right:5.1%;top:26%;width:180px;padding:14px 0;border-top:1px solid rgba(255,255,255,.22);border-bottom:1px solid rgba(255,255,255,.22)}
.stat{margin:0 0 16px}
.stat>span{font:9px 'DM Mono',monospace;letter-spacing:1.4px;color:#b9b8ad}
.stat-row{display:flex;align-items:center;gap:9px;margin-top:6px}
.stat-row b{font:19px 'DM Mono',monospace;font-weight:400;width:28px}
.meter{height:3px;background:#515450;flex:1}
.meter i{height:100%;display:block;width:86%;background:#a7ad8a;transition:width .4s}
.meter.stress i{background:#bd7768}
.stat-unit{font:9px 'DM Mono',monospace;color:#a6a69a}
.weather-note{font:9px 'DM Mono',monospace;color:#aaa99e;margin-top:12px}
.crosshair{position:absolute;z-index:3;left:50%;top:49%;width:12px;height:12px;transform:translate(-50%,-50%);opacity:.85;pointer-events:none}
.crosshair i,.crosshair b{position:absolute;background:rgba(237,231,211,.84)}
.crosshair i{width:1px;height:12px;left:5px}
.crosshair b{width:12px;height:1px;top:5px}
.interaction-prompt{position:absolute;z-index:4;left:50%;top:54%;transform:translateX(-50%);padding:9px 14px;background:rgba(11,15,14,.82);border:1px solid rgba(226,211,172,.35);font:10px 'DM Mono',monospace;letter-spacing:.8px;color:#e5ddc8;opacity:0;transition:opacity .15s;white-space:nowrap;pointer-events:none}
.interaction-prompt.show{opacity:1}
.interaction-prompt kbd{color:#d5b978;margin-right:8px}
.toast{position:absolute;z-index:8;top:86px;left:50%;transform:translate(-50%,-10px);opacity:0;transition:.3s;background:rgba(14,19,17,.92);padding:11px 18px;border:1px solid rgba(202,177,116,.36);font:10px 'DM Mono',monospace;letter-spacing:.5px;color:#e5d8b8;pointer-events:none}
.toast.show{opacity:1;transform:translate(-50%,0)}
.bottom-hud{position:absolute;z-index:4;bottom:0;left:0;right:0;height:82px;padding:0 36px;display:flex;align-items:center;justify-content:space-between;background:linear-gradient(0deg,rgba(6,10,9,.94),rgba(8,12,11,.76));border-top:1px solid rgba(255,255,255,.1)}
.control-hint{display:flex;align-items:center;gap:5px;color:#a8a99e;font:9px 'DM Mono',monospace;letter-spacing:.8px}
.control-hint kbd,.key-grid kbd{font:10px 'DM Mono',monospace;color:#d6d3c7;border:1px solid rgba(255,255,255,.24);padding:5px 6px;min-width:23px;text-align:center}
.control-hint span{margin:0 8px 0 3px;color:#888b83;font-size:8px}
.bottom-hud nav{height:100%;display:flex;gap:8px;align-items:center}
.nav-button{cursor:pointer;background:transparent;border:1px solid transparent;padding:12px;color:#b9b9ae;font:9px 'DM Mono',monospace;letter-spacing:1px}
.nav-button span{font-size:15px;margin-right:7px}
.nav-button b{margin-left:7px;color:var(--gold);font-size:10px}
.nav-button.active{border-color:rgba(200,177,119,.4);color:#e0d1a7;background:rgba(197,167,102,.08)}
.radio{width:200px;display:flex;align-items:center;gap:10px;border-left:1px solid rgba(255,255,255,.18);padding-left:19px;color:#d5d2c4}
.radio>span{font-size:20px;color:#cfb67e}
.radio b{font:9px 'DM Mono',monospace;letter-spacing:1px;display:block}
.radio small{font-size:10px;color:#aaa99e;display:block;margin-top:3px}
.panel{position:absolute;z-index:7;right:0;top:74px;bottom:82px;width:min(470px,94vw);background:var(--panel);backdrop-filter:blur(16px);border-left:1px solid rgba(219,202,162,.24);box-shadow:-20px 0 60px #0008;animation:slide .2s ease-out;display:flex;flex-direction:column}
.panel.hidden,.hidden{display:none!important}
@keyframes slide{from{transform:translateX(20px);opacity:.5}
to{transform:translateX(0);opacity:1}
}
.panel-head{padding:27px 28px 18px;border-bottom:1px solid var(--line);display:flex;align-items:flex-start;justify-content:space-between}
.panel-head h2,.person-head h2{font:500 26px 'Playfair Display',serif;margin:7px 0 0}
.close-btn{border:0;background:transparent;color:#aaa99e;font-size:25px;line-height:1;cursor:pointer}
.close-btn:hover{color:var(--gold)}
.panel-content{overflow:auto;padding:21px 28px 30px}
.tab-row{display:flex;gap:4px;border-bottom:1px solid var(--line);margin:-7px 0 20px}
.tab{background:none;border:0;border-bottom:1px solid transparent;padding:0 12px 10px;color:#999b92;font:9px 'DM Mono',monospace;letter-spacing:.8px;cursor:pointer}
.tab.selected{color:var(--gold);border-color:var(--gold)}
.evidence-card,.file-card,.note-card,.person-card{border:1px solid var(--line);padding:15px 16px;margin:0 0 10px;background:rgba(255,255,255,.025)}
.card-top{display:flex;justify-content:space-between;align-items:center}
.card-top strong{font:500 14px 'DM Sans',sans-serif}
.tag{font:8px 'DM Mono',monospace;letter-spacing:.8px;padding:4px 6px;color:#c7af78;border:1px solid rgba(199,175,120,.35)}
.tag.verified{color:#9eaf93;border-color:#78906c}
.tag.rumor{color:#cc8d80;border-color:#a7655a}
.evidence-card p,.file-card p,.note-card p,.person-card p{color:#b4b5aa;font-size:12px;line-height:1.55;margin:9px 0 0}
.card-foot{font:9px 'DM Mono',monospace;color:#858a80;margin-top:11px;letter-spacing:.5px}
.action-row{display:flex;gap:8px;margin-top:13px}
.small-btn{cursor:pointer;border:1px solid rgba(208,190,144,.34);background:rgba(195,169,112,.08);color:#d8c696;padding:8px 11px;font:9px 'DM Mono',monospace;letter-spacing:.5px}
.small-btn:hover{background:rgba(195,169,112,.18)}
.small-btn:disabled{opacity:.42;cursor:default}
.empty-state{text-align:center;padding:35px 20px;color:#aaa99d}
.empty-state .empty-symbol{font-size:30px;color:#887e68;margin-bottom:12px}
.empty-state h3{font:500 18px 'Playfair Display',serif;color:#d4d0c3}
.empty-state p{font-size:12px;line-height:1.65}
.section-label{font:9px 'DM Mono',monospace;letter-spacing:1.3px;color:#a6a397;margin:20px 0 11px}
.intel-box{border-left:2px solid #ae9967;padding:10px 13px;background:rgba(190,164,103,.07);font-size:11px;color:#c7c4b8;line-height:1.6;margin:11px 0}
.map-wrap{background:#111816;border:1px solid var(--line);padding:8px}
.map-wrap svg{width:100%;height:auto}
.map-legend{display:flex;gap:13px;flex-wrap:wrap;font:9px 'DM Mono',monospace;color:#a3a59b;margin-top:12px}
.legend-dot{display:inline-block;width:7px;height:7px;background:#ba715f;border-radius:50%;margin-right:5px}
.map-loc{fill:#626a60;stroke:#9b9e8a;stroke-width:1}
.map-road{stroke:#252e2b;stroke-width:18}
.map-text{fill:#b5b39f;font:7px 'DM Mono',monospace;letter-spacing:1px}
.map-mark{fill:#c67764;stroke:#f0b495;stroke-width:1.4}
.dialogue{position:absolute;z-index:8;inset:0;background:rgba(3,7,7,.45);display:flex;align-items:flex-end;justify-content:center;padding-bottom:102px}
.dialogue-card{width:min(580px,92vw);background:rgba(15,20,19,.96);border:1px solid rgba(226,213,177,.28);padding:22px 26px 23px;box-shadow:0 20px 90px #0009}
.person-head{display:flex;align-items:center;gap:13px;border-bottom:1px solid var(--line);padding-bottom:15px}
.person-head>div:nth-child(2){flex:1}
.avatar{height:42px;width:42px;border:1px solid rgba(197,169,106,.55);display:grid;place-items:center;color:#c9ae72;font:19px 'Playfair Display',serif;background:rgba(197,169,106,.1)}
.person-head h2{font-size:20px}
.dialogue-card>p{font:14px/1.75 'Playfair Display',serif;color:#d1cec0;margin:18px 0}
.dialogue-options{display:grid;gap:7px}
.dialogue-option{cursor:pointer;text-align:left;background:rgba(255,255,255,.025);border:1px solid var(--line);padding:11px 13px;color:#c6c5ba;font-size:11px}
.dialogue-option:hover{border-color:rgba(197,169,106,.58);color:#e1d1a8}
.dialogue-option small{float:right;color:#9e9c90;font:9px 'DM Mono',monospace}
.screen-cover{position:absolute;inset:0;z-index:10;display:flex;align-items:center;justify-content:center;background:linear-gradient(90deg,rgba(5,10,9,.91),rgba(5,10,9,.54) 57%,rgba(5,10,9,.46)),linear-gradient(0deg,rgba(5,8,7,.3),transparent),#18201d}
.start-bg{position:absolute;inset:0;background:radial-gradient(ellipse at 70% 55%,rgba(142,123,83,.11),transparent 37%),linear-gradient(180deg,transparent 55%,rgba(8,12,10,.7)),repeating-linear-gradient(90deg,transparent 0 9%,rgba(180,172,137,.018) 9.2% 9.3%),radial-gradient(ellipse at 74% 100%,#39443a 0 10%,#202923 25%,transparent 58%);pointer-events:none}
.title-wrap{position:relative;z-index:1;width:min(550px,88vw);margin-left:-28%;padding-top:10px}
.title-eyebrow{display:flex;align-items:center;gap:10px;font:9px 'DM Mono',monospace;letter-spacing:2px;color:#c6b689}
.title-eyebrow span{width:20px;height:1px;background:#b9a16c}
.title-wrap h1{font:500 clamp(54px,8vw,91px)/1 'Playfair Display',serif;letter-spacing:8px;margin:21px 0 3px;color:#e5e1d5;text-shadow:0 4px 30px #000}
.subtitle{font:10px 'DM Mono',monospace;letter-spacing:4.7px;color:#c6b78f;margin-left:6px}
.title-rule{display:flex;align-items:center;gap:11px;color:#bda56f;font-size:17px;margin:28px 0 17px;width:230px}
.title-rule i{height:1px;flex:1;background:rgba(202,177,116,.45)}
.title-wrap>p{font:15px/1.8 'Playfair Display',serif;color:#bdbdb0;margin:0 0 25px}
.primary-btn{cursor:pointer;border:1px solid #b9a46e;background:rgba(177,148,88,.12);padding:14px 19px;color:#e4d7ae;font:10px 'DM Mono',monospace;letter-spacing:1.5px;transition:.2s}
.primary-btn:hover{background:#ae9460;color:#141813}
.primary-btn span{margin-left:29px;font-size:15px}
.start-foot{font:8px 'DM Mono',monospace;letter-spacing:1px;color:#777e74;margin-top:34px}
.modal{position:absolute;z-index:12;inset:0;background:rgba(3,6,6,.72);display:grid;place-items:center}
.modal-card{position:relative;width:min(470px,90vw);padding:34px;background:#141b18;border:1px solid rgba(219,202,162,.25);box-shadow:0 20px 90px #000}
.modal-close{position:absolute;right:17px;top:15px}
.modal-card h2{font:500 28px 'Playfair Display',serif;margin:10px 0}
.modal-card p{font-size:13px;line-height:1.7;color:#b9baaf}
.key-grid{display:grid;grid-template-columns:1fr 1fr;gap:13px;margin:22px 0}
.key-grid span{font-size:11px;color:#c9c7bc;display:flex;align-items:center;gap:8px}
.muted{color:#92958b!important;font-size:11px!important}
.modal-ok{margin-top:7px}
.ending{background:rgba(7,10,9,.94)}
#ending .title-wrap{margin:0}
.ending #endingText{max-width:430px}
.mobile-controls{display:none}
@media(max-width:850px){.topbar{height:60px;padding:0 17px}
.top-center{gap:7px;font-size:8px}
.brand-name{font-size:10px;letter-spacing:1.5px}
.brand-sub{font-size:7px}
.brand-mark{font-size:23px}
.hud-left{left:5%;top:20%;width:250px}
.hud-left h1{font-size:30px}
.hud-right{right:4%;top:22%;width:145px}
.bottom-hud{height:75px;padding:0 12px}
.control-hint{display:none}
.radio{width:auto;padding-left:9px;border:0}
.radio small{display:none}
.nav-button{padding:11px 7px;font-size:8px}
.nav-button span{margin-right:3px}
.panel{top:60px;bottom:75px}
.title-wrap{margin-left:-10%}
}
@media(max-width:560px){#game{min-height:420px}
.top-center{position:absolute;top:61px;left:18px;background:rgba(7,10,9,.48);padding:6px 9px}
.topbar{height:56px}
.hud-left{top:17%;width:215px}
.hud-left h1{font-size:28px;margin:9px 0}
.hud-left p{font-size:11px;margin-bottom:13px}
.hud-right{top:auto;bottom:103px;right:12px;width:124px;padding:8px 0}
.stat{margin-bottom:8px}
.stat>span{font-size:8px}
.stat-row b{font-size:15px}
.weather-note{font-size:8px;margin-top:6px}
.bottom-hud{height:68px;padding:0 4px}
.bottom-hud nav{gap:0}
.nav-button{padding:10px 6px;font-size:7px;letter-spacing:.3px}
.nav-button span{font-size:12px}
.radio{display:none}
.panel{top:56px;bottom:68px;width:100%}
.panel-head{padding:20px 20px 14px}
.panel-content{padding:16px 20px}
.title-wrap{margin-left:0;width:88vw}
.title-wrap h1{font-size:54px;letter-spacing:4px}
.subtitle{letter-spacing:2.4px}
.title-wrap>p{font-size:13px}
.start-foot{font-size:7px}
.dialogue{padding-bottom:80px}
.dialogue-card{padding:17px}
.interaction-prompt{top:57%}
}

